const created=[],mutated=[],links=[],screens={},styleTasks=[];
let theme='light',screenKey='',live=true;
const rgb=h=>({r:parseInt(h.slice(1,3),16)/255,g:parseInt(h.slice(3,5),16)/255,b:parseInt(h.slice(5,7),16)/255});
const solid=(h,opacity=1)=>({type:'SOLID',color:rgb(h),opacity});
const fallback={light:{panel:'#F8FAFB',border:'#E4E7E9'},dark:{panel:'#202124',border:'#363A3D'}};const paint=role=>figma.variables.setBoundVariableForPaint(solid(fallback[theme][role]||'#000000'),'color',V[theme+'/'+role]);
