function track(n){created.push(n.id);return n;}
function frame(parent,name,w,h,x=0,y=0,role=null,r=0){const n=track(figma.createFrame());parent.appendChild(n);n.name=name;n.resize(w,h);n.x=x;n.y=y;n.fills=role?[paint(role)]:[];n.cornerRadius=r;n.clipsContent=false;return n;}
function box(parent,name,w,h,x,y,role='panel',r=24){const n=frame(parent,name,w,h,x,y,role,r);n.strokes=[paint('border')];n.strokeWeight=.6;n.effects=[{type:'DROP_SHADOW',color:{r:0,g:0,b:0,a:theme==='dark'?.12:.045},offset:{x:0,y:9},radius:24,visible:true,blendMode:'NORMAL'}];return n;}
function stack(parent,name,w,x=0,y=0,gap=16,pad=0,role=null){const n=track(figma.createAutoLayout('VERTICAL'));parent.appendChild(n);n.name=name;n.resize(w,10);n.primaryAxisSizingMode='AUTO';n.counterAxisSizingMode='FIXED';n.itemSpacing=gap;n.paddingTop=pad;n.paddingBottom=pad;n.paddingLeft=pad;n.paddingRight=pad;n.fills=role?[paint(role)]:[];n.x=x;n.y=y;return n;}
function rowstack(parent,name,w,h,gap=12){const n=track(figma.createAutoLayout('HORIZONTAL'));parent.appendChild(n);n.name=name;n.resize(w,h);n.primaryAxisSizingMode='FIXED';n.counterAxisSizingMode='FIXED';n.counterAxisAlignItems='CENTER';n.itemSpacing=gap;n.fills=[];return n;}
function t(parent,value,w=350,size=17,role='ink',weight=null,name=null){const n=track(figma.createText());parent.appendChild(n);n.name=name||value.slice(0,36);const preset=styleMap[size];const fontStyle=weight||preset?.[1]||'Regular';n.fontName={family:'Noto Sans SC',style:fontStyle};n.fontSize=size;n.lineHeight={unit:'PIXELS',value:preset?.[2]||Math.ceil(size*1.4)};n.characters=value;n.fills=[paint(role)];n.textAutoResize='HEIGHT';n.resize(w,Math.ceil(size*1.4));if(preset&&!weight)styleTasks.push(n.setTextStyleIdAsync(STATE.styles[preset[0]]));return n;}
function at(n,x,y){n.x=x;n.y=y;return n;}
function route(n,target,event='ON_CLICK'){if(live&&target)links.push({from:n.id,target:target.includes('/')?target:theme+'/'+target,event,owner:screenKey});return n;}
