function circleButton(parent,kind,x,y,target,size=44){const b=box(parent,'Action/'+kind,size,size,x,y,'panel',size/2);icon(b,kind,(size-24)/2,(size-24)/2);route(b,target);return b;}
function instance(parent,key,x=0,y=0,props={}){const n=track(C[key+'/'+theme].createInstance());parent.appendChild(n);n.x=x;n.y=y;for(const[name,value]of Object.entries(props)){const node=n.findOne(a=>a.type==='TEXT'&&a.name===name);if(node){node.characters=value;mutated.push(node.id);}}return n;}
function button(parent,label,target,kind='Primary',w=350){const b=instance(parent,'Button/'+kind,0,0,{Label:label});b.resize(w,52);const l=b.findOne(a=>a.type==='TEXT'&&a.name==='Label');if(l){l.resize(w-32,l.height);mutated.push(l.id);}if(kind!=='Disabled')route(b,target);return b;}
function field(parent,label,value){const n=instance(parent,'Field',0,0,{Label:label,Value:value});const v=n.findOne(a=>a.type==='TEXT'&&a.name==='Value');if(v)n.resize(350,Math.max(78,v.height+51));return n;}
function listrow(parent,label,value,target,w=350){const r=instance(parent,'ListRow',0,0,{Label:label,Value:value||'›'});r.resize(w,62);route(r,target);return r;}
function hint(parent,value,role='muted'){return t(parent,value,350,13,role);}
