function settlement(s,fx=false,accepted=false){const{body}=sheet(s,fx?'结算与汇率核对':'结算核对',60);if(!fx){const pending=s.findOne(n=>n.name==='Pending summary');if(pending)for(const n of pending.findAll(n=>n.type==='TEXT'))n.characters=n.characters.includes('待确认')?'待确认已处理':'¥0';}hint(body,fx?'独立示例：旅行预算 · USD':'日常生活 · 本期');t(body,fx?'USD 120':'¥1,280',350,34);hint(body,'本次预算结余');listrow(body,'预算额度',fx?'USD 400':'¥3,000');listrow(body,'已确认支出',fx?'USD 280':'¥1,720');listrow(body,'待确认','0 笔');if(fx){field(body,'汇率','1 USD = 7.20 CNY');field(body,'来源与时间','用户核对 · 2026年11月5日');hint(body,'本次转入 CNY 864；确认时保存汇率快照。');}else hint(body,'本期今天提前结束，下期仍于12月1日开始。');field(body,'心愿余额',fx?'¥860 → ¥1,724':'¥860 → ¥2,140');const accept=box(body,'Coverage acknowledgement',350,92,0,0,'panel',20);const check=frame(accept,'Checkbox',22,22,16,20,accepted?'ink':null,6);check.strokes=[paint('muted')];if(accepted)icon(check,'check',2,2,18,'onPrimary');at(t(accept,'我已核对记录，并接受当前数据覆盖范围。',285,16),51,16);route(accept,fx?'settlement-fx-accepted':'settlement-accepted');button(body,'确认结算',fx?'settlement-fx-success':'early-settlement-waiting',accepted?'Primary':'Disabled');button(body,'返回核对记录','records','Secondary');}
