function state(s,data){header(s,data.title,Object.hasOwn(data,'backTarget')?data.backTarget:(data.links?.[0]||'budgets'),true);const viewport=frame(s,'Scrollable state',350,700,26,150);viewport.clipsContent=true;viewport.overflowDirection='VERTICAL';const body=stack(viewport,'State content',350,0,0,20);hint(body,data.eyebrow,'accent');t(body,data.headline,350,29);t(body,data.body,350,17,'muted');for(const row of data.rows)field(body,row.label,row.value);if(data.primary)button(body,data.primary,Object.hasOwn(data,'primaryTarget')?data.primaryTarget:data.links?.[0]);if(data.secondary)button(body,data.secondary,Object.hasOwn(data,'secondaryTarget')?data.secondaryTarget:(data.links?.[1]||data.links?.[0]),'Secondary'); if(data.systemAction){for(const [slot,action] of Object.entries(data.systemAction)){const n=body.children.find(c=>c.type==='INSTANCE' && c.findOne(x=>x.type==='TEXT'&&x.characters===data[slot]));if(n&&!data[slot+'Target']) n.systemAction=action;}}}
function make(key,index,themeName,data=null){const s=root(key,data?.title||key,index,themeName);switch(key){case'budgets':home(s);break;case'records-layer':records(s,true);break;case'library':library(s);break;case'library-sphere':library(s,true);break;case'budget-detail':details(s);break;case'records':records(s);break;case'expense-detail':recordDetail(s);break;case'calendar':calendar(s);break;case'history-review':history(s);break;case'budget-info':info(s);break;case'wishes':wishes(s);break;case'collection':wishes(s,true,true);break;case'collection-redeemed':wishes(s,true,true,true);break;case'wishes-list':{header(s,'心愿','wishes');const b=stack(s,'Wish list',350,26,150,16);listrow(b,'一副新耳机','¥699','wish-front');listrow(b,'去山里露营','¥1,200','wish-insufficient');listrow(b,'一本好书','¥89','wish-front');break;}case'wish-expanded':expandedWish(s);break;case'wish-front':expandedWish(s,true);break;case'collection-back':expandedWish(s,false,true);break;case'wallet':wallet(s);break;case'wallet-entry':wallet(s,true);break;case'record':case'create-budget':case'create-wish':form(s,key);break;case'wish-cover':cover(s);break;case'agent':agent(s);break;case'settings':settings(s);break;case'settlement-fx':settlement(s,true);break;case'settlement-fx-accepted':settlement(s,true,true);break;case'settlement-review':settlement(s,false);break;case'settlement-accepted':settlement(s,false,true);break;case'redemption':redemption(s);break;case'redemption-checked':redemption(s,true);break;default:if(!data)throw new Error('Missing content '+key);state(s,data);}
 return s;}
for(const spec of BATCH)make(spec.key,spec.index,spec.theme,spec.data||null);
await Promise.all(styleTasks);
